16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "postcode")
48	    @Pattern(regexp = "^[0-9]{4}$", message = "Postcode must be 4 digits")
49	    private String postcode;
50	
51	    @Column(name = "telephone")
52	    @NotEmpty
53	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form ('+' and 8 to 15 digits)")
54	    private String telephone;
55	
56	    @Column(name = "email")
57	    @Email
58	    private String email;
59	
60	    @Column(name = "registration_date")
61	    private LocalDate registrationDate;
62	
63	    @Column(name = "customer_code")
64	    private String customerCode;
65	
66	    @Column(name = "household_id")
67	    private String householdId;
68	
69	    @Column(name = "namesake_count")
70	    private Integer namesakeCount;
71	
72	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
73	    private Set<Pet> pets;
74	
75	    public String getAddress() {
76	        return this.address;
77	    }
78	
79	    public void setAddress(String address) {
80	        this.address = address;
81	    }
82	
83	    public String getCity() {
84	        return this.city;
85	    }
86	
87	    public void setCity(String city) {
88	        this.city = city;
89	    }
90	
91	    public String getPostcode() {
92	        return this.postcode;
93	    }
94	
95	    public void setPostcode(String postcode) {
96	        this.postcode = postcode;
97	    }
98	
99	    public String getTelephone() {
100	        return this.telephone;
101	    }
102	
103	    public void setTelephone(String telephone) {
104	        this.telephone = telephone;
105	    }
106	
107	    public String getEmail() {
108	        return this.email;
109	    }
110	
111	    public void setEmail(String email) {
112	        this.email = email;
113	    }
114	
115	    public LocalDate getRegistrationDate() {
116	        return this.registrationDate;
117	    }
118	
119	    public void setRegistrationDate(LocalDate registrationDate) {
120	        this.registrationDate = registrationDate;
121	    }
122	
123	    public String getCustomerCode() {
124	        return this.customerCode;
125	    }
126	
127	    public void setCustomerCode(String customerCode) {
128	        this.customerCode = customerCode;
129	    }
130	
131	    public String getHouseholdId() {
132	        return this.householdId;
133	    }
134	
135	    public void setHouseholdId(String householdId) {
136	        this.householdId = householdId;
137	    }
138	
139	    public Integer getNamesakeCount() {
140	        return this.namesakeCount;
141	    }
142	
143	    public void setNamesakeCount(Integer namesakeCount) {
144	        this.namesakeCount = namesakeCount;
145	    }
146	
147	    protected Set<Pet> getPetsInternal() {
148	        if (this.pets == null) {
149	            this.pets = new HashSet<>();
150	        }
151	        return this.pets;
152	    }
153	
154	    protected void setPetsInternal(Set<Pet> pets) {
155	        this.pets = pets;
156	    }
157	
158	    public List<Pet> getPets() {
159	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
160	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
161	        return Collections.unmodifiableList(sortedPets);
162	    }
163	
164	    public void setPets(List<Pet> pets) {
165	        this.pets = new HashSet<>(pets);
166	    }
167	
168	    public void addPet(Pet pet) {
169	        getPetsInternal().add(pet);
170	        pet.setOwner(this);
171	    }
172	
173	    /**
174	     * Return the Pet with the given name, or null if none found for this Owner.
175	     *
176	     * @param name to test
177	     * @return true if pet name is already in use
178	     */
179	    public Pet getPet(String name) {
180	        return getPet(name, false);
181	    }
182	
183	    /**
184	     * Return the Pet with the given name, or null if none found for this Owner.
185	     *
186	     * @param name to test
187	     * @return true if pet name is already in use
188	     */
189	    public Pet getPet(String name, boolean ignoreNew) {
190	        name = name.toLowerCase();
191	        for (Pet pet : getPetsInternal()) {
192	            if (!ignoreNew || !pet.isNew()) {
193	                String compName = pet.getName();
194	                compName = compName.toLowerCase();
195	                if (compName.equals(name)) {
196	                    return pet;
197	                }
198	            }
199	        }
200	        return null;
201	    }
202	
203	    public Pet getPet(Integer petId) {
204	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
205	    }
206	
207	    @Override
208	    public String toString() {
209	        return new ToStringCreator(this)
210	
211	            .append("id", this.getId())
212	            .append("new", this.isNew())
213	            .append("lastName", this.getLastName())
214	            .append("firstName", this.getFirstName())
215	            .append("address", this.address)
216	            .append("city", this.city)
217	            .append("telephone", this.telephone)
218	            .toString();
219	    }
220	}
