33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Region;
38	import org.springframework.samples.petclinic.model.Visit;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
41	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.PetDto;
43	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
46	import org.springframework.samples.petclinic.service.ClinicService;
47	import org.springframework.samples.petclinic.rest.advice.DailyOwnerRegistrationLimitException;
48	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerIdentityException;
49	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
50	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerPostcodeException;
51	import org.springframework.samples.petclinic.rest.advice.OwnerCityAtCapacityException;
52	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
53	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
54	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
55	import org.springframework.security.access.prepost.PreAuthorize;
56	import org.springframework.web.bind.annotation.CrossOrigin;
57	import org.springframework.web.bind.annotation.RequestMapping;
58	import org.springframework.web.bind.annotation.RestController;
59	import org.springframework.web.util.UriComponentsBuilder;
60	
61	import jakarta.transaction.Transactional;
62	
63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
73	
74	    private final ClinicService clinicService;
75	
76	    private final OwnerMapper ownerMapper;
77	
78	    private final PetMapper petMapper;
79	
80	    private final VisitMapper visitMapper;
81	
82	    private final TelephoneNormalizer telephoneNormalizer;
83	
84	    private final AddressNormalizer addressNormalizer;
85	
86	    private final EmailNormalizer emailNormalizer;
87	
88	    public OwnerRestControllerV1(ClinicService clinicService,
89	                                 OwnerMapper ownerMapper,
90	                                 PetMapper petMapper,
91	                                 VisitMapper visitMapper,
92	                                 TelephoneNormalizer telephoneNormalizer,
93	                                 AddressNormalizer addressNormalizer,
94	                                 EmailNormalizer emailNormalizer) {
95	        this.clinicService = clinicService;
96	        this.ownerMapper = ownerMapper;
97	        this.petMapper = petMapper;
98	        this.visitMapper = visitMapper;
99	        this.telephoneNormalizer = telephoneNormalizer;
100	        this.addressNormalizer = addressNormalizer;
101	        this.emailNormalizer = emailNormalizer;
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
107	        Collection<Owner> owners;
108	        if (lastName != null) {
109	            owners = this.clinicService.findOwnerByLastName(lastName);
110	        } else {
111	            owners = this.clinicService.findAllOwners();
112	        }
113	        if (owners.isEmpty()) {
114	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
115	        }
116	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
122	        return withOwner(ownerId, owner ->
123	            new ResponseEntity<>(toOwnerDtoWithDerivedFields(owner), HttpStatus.OK));
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
129	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
130	        rejectBlankOwnerFields(ownerFieldsDto);
131	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
132	        rejectInvalidPostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
133	        rejectCityAtCapacity(ownerFieldsDto.getCity());
134	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
135	        rejectDailyRegistrationLimit(registrationDate);
136	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
137	        ownerFieldsDto.setTelephone(normalizedTelephone);
138	        String normalizedEmail = emailNormalizer.normalize(ownerFieldsDto.getEmail());
139	        ownerFieldsDto.setEmail(normalizedEmail);
140	        HttpHeaders headers = new HttpHeaders();
141	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
142	        owner.setRegistrationDate(registrationDate);
143	        owner.setCustomerCode(customerCode(owner));
144	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
145	        if (sharesHousehold) {
146	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
147	        }
148	        rejectDuplicateIdentity(owner);
149	        this.clinicService.saveOwner(owner);
150	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
151	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
152	            ownerMapper.membershipLevel(owner));
153	        OwnerDto ownerDto = toOwnerDtoWithDerivedFields(owner);
154	        headers.setLocation(UriComponentsBuilder.newInstance()
155	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
156	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
162	        return withOwner(ownerId, currentOwner -> {
163	            currentOwner.setAddress(ownerFieldsDto.getAddress());
164	            currentOwner.setCity(ownerFieldsDto.getCity());
165	            currentOwner.setFirstName(ownerFieldsDto.getFirstName());
166	            currentOwner.setLastName(ownerFieldsDto.getLastName());
167	            currentOwner.setTelephone(ownerFieldsDto.getTelephone());
168	            currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
169	            this.clinicService.saveOwner(currentOwner);
170	            return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
171	        });
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Transactional
176	    @Override
177	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
178	        return withOwner(ownerId, owner -> {
179	            this.clinicService.deleteOwner(owner);
180	            return new ResponseEntity<>(HttpStatus.NO_CONTENT);
181	        });
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
187	        return withOwner(ownerId, owner -> {
188	            HttpHeaders headers = new HttpHeaders();
189	            Pet pet = petMapper.toPet(petFieldsDto);
190	            owner.setId(ownerId);
191	            pet.setOwner(owner);
192	            pet.getType().setName(null);
193	            this.clinicService.savePet(pet);
194	            PetDto petDto = petMapper.toPetDto(pet);
195	            headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
196	                .buildAndExpand(pet.getId()).toUri());
197	            return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
198	        });
199	    }
200	
201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Override
203	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
204	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
205	        if (currentOwner != null) {
206	            Pet currentPet = this.clinicService.findPetById(petId);
207	            if (currentPet != null) {
208	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
209	                currentPet.setName(petFieldsDto.getName());
210	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
211	                this.clinicService.savePet(currentPet);
212	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
213	            }
214	        }
215	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	    }
217	
218	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
219	    @Override
220	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
221	        HttpHeaders headers = new HttpHeaders();
222	        Visit visit = visitMapper.toVisit(visitFieldsDto);
223	        Pet pet = new Pet();
224	        pet.setId(petId);
225	        visit.setPet(pet);
226	        this.clinicService.saveVisit(visit);
227	        VisitDto visitDto = visitMapper.toVisitDto(visit);
228	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
229	            .buildAndExpand(visit.getId()).toUri());
230	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
231	    }
232	
233	
234	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
235	    @Override
236	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
237	        Owner owner = this.clinicService.findOwnerById(ownerId);
238	        if (owner != null) {
239	            Pet pet = owner.getPet(petId);
240	            if (pet != null) {
241	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
242	            }
243	        }
244	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
245	    }
246	
247	    /**
248	     * Loads the owner with the given id and, when it exists, produces the response through
249	     * {@code action}; when no such owner exists a {@code 404 Not Found} is returned instead. The
250	     * single-owner endpoints share this "find the owner or report 404" preamble, so the lookup and
251	     * the not-found response are written in exactly one place rather than copied into each method.
252	     *
253	     * @param ownerId the id of the owner to load
254	     * @param action builds the response for an existing owner
255	     * @param <T> the response body type
256	     * @return the result of {@code action} for an existing owner, otherwise a 404 response
257	     */
258	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> action) {
259	        Owner owner = this.clinicService.findOwnerById(ownerId);
260	        if (owner == null) {
261	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
262	        }
263	        return action.apply(owner);
264	    }
265	
266	    /**
267	     * Maps a persisted owner to its {@link OwnerDto} and populates the read-only fields that are
268	     * derived from server-side state rather than stored columns (the {@code bulkSignupWarning} flag
269	     * and the {@code identityKey}). Both the create endpoint and the single-owner read endpoint
270	     * return their owner through this method, so an owner is decorated identically on either path
271	     * and each derived field is computed in exactly one place.
272	     *
273	     * @param owner the persisted owner to represent
274	     * @return the owner DTO with its derived read-only fields populated
275	     */
276	    private OwnerDto toOwnerDtoWithDerivedFields(Owner owner) {
277	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
278	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
279	        ownerDto.setIdentityKey(identityKey(owner));
280	        return ownerDto;
281	    }
282	
283	    /**
284	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
285	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
286	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
287	     * blank (e.g. {@code "   "}). The offending field names are reported through an
288	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
289	     * as a 400 response carrying an {@code errors} array of field names.
290	     *
291	     * @param ownerFieldsDto the submitted owner fields
292	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
293	     */
294	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
295	        List<String> blankFields = new ArrayList<>();
296	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
297	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
298	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
299	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
300	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
301	        if (!blankFields.isEmpty()) {
302	            throw new InvalidOwnerFieldsException(blankFields);
303	        }
304	    }
305	
306	    private void addIfBlank(List<String> blankFields, String field, String value) {
307	        if (value != null && value.isBlank()) {
308	            blankFields.add(field);
309	        }
310	    }
311	
312	    /**
313	     * Validates the owner's optional {@code postcode} against its {@code city} region. Postcode is
314	     * validated only when present, so an owner created without one is accepted unchanged. A supplied
315	     * postcode is already constrained to four digits by Bean Validation on {@link OwnerFieldsDto}; this
316	     * additionally rejects a well-formed postcode that is out of range for the city's region using the
317	     * shared {@link Region#acceptsPostcode(int) region-to-postcode} table ({@code NSW 2000-2099},
318	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known region accepts any 4-digit
319	     * postcode. An out-of-range postcode is reported through an {@link InvalidOwnerPostcodeException},
320	     * which the {@code ExceptionControllerAdvice} renders as a 400 response.
321	     *
322	     * @param city the city of the owner being created
323	     * @param postcode the supplied postcode, or {@code null} when omitted
324	     * @throws InvalidOwnerPostcodeException if the postcode is out of range for the city's region
325	     */
326	    private void rejectInvalidPostcode(String city, String postcode) {
327	        if (postcode == null || postcode.isBlank()) {
328	            return;
329	        }
330	        Region.forCity(city).ifPresent(region -> {
331	            if (!region.acceptsPostcode(Integer.parseInt(postcode))) {
332	                throw new InvalidOwnerPostcodeException(postcode, city);
333	            }
334	        });
335	    }
336	
337	    /**
338	     * Number of leading hex characters of the identity hash retained as the {@code HASH8} segment of
339	     * the {@code customerCode}.
340	     */
341	    private static final int CUSTOMER_CODE_HASH_LENGTH = 8;
342	
343	    /**
344	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
345	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the owner's canonical region code resolved from
346	     * its {@code postcode} (falling back to its {@code city}) through the shared
347	     * {@link Region#code(String, String)}, and {@code HASH8} is the first 8 upper-case hex characters
348	     * of the SHA-256 digest of the owner's normalized telephone followed by its last name
349	     * (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a deterministic
350	     * function of the owner's region and telephone-plus-name identity.
351	     *
352	     * @param owner the owner being created, with its telephone already normalized
353	     * @return the formatted customer code
354	     */
355	    private String customerCode(Owner owner) {
356	        String region = Region.code(owner.getPostcode(), owner.getCity());
357	        String hash8 = hashPrefix(owner.getTelephone() + owner.getLastName(), CUSTOMER_CODE_HASH_LENGTH);
358	        return region + "-" + hash8;
359	    }
360	
361	    /**
362	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
363	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
364	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
365	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
366	     * new owner and surfaced as the read-only {@code namesakeCount} field.
367	     *
368	     * @param firstName the first name of the owner being created
369	     * @param lastName the last name of the owner being created
370	     * @return the number of existing owners with the same first and last name (case-insensitive)
371	     */
372	    private int namesakeCount(String firstName, String lastName) {
373	        return (int) this.clinicService.findAllOwners().stream()
374	            .filter(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
375	                && equalsIgnoreCase(owner.getLastName(), lastName))
376	            .count();
377	    }
378	
379	    private boolean equalsIgnoreCase(String a, String b) {
380	        return a == null ? b == null : a.equalsIgnoreCase(b);
381	    }
382	
383	    /**
384	     * The maximum number of owners a single city may contain. Once a city already holds this many
385	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
386	     */
387	    private static final long MAX_OWNERS_PER_CITY = 50L;
388	
389	    /**
390	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
391	     * owners. Existing owners are matched to the requested city case-insensitively (using
392	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
393	     * the per-city counting used for the customer code. A city at capacity is reported through an
394	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
395	     * 409 Conflict response.
396	     *
397	     * @param city the city of the owner being created
398	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
399	     */
400	    private void rejectCityAtCapacity(String city) {
401	        if (ownersInCity(city) >= MAX_OWNERS_PER_CITY) {
402	            throw new OwnerCityAtCapacityException(city);
403	        }
404	    }
405	
406	    /**
407	     * Counts the existing owners whose {@code city} matches the given city, compared
408	     * case-insensitively (see {@link #equalsIgnoreCase(String, String)}). Used by the per-city
409	     * capacity check ({@link #rejectCityAtCapacity(String)}) to count a city's owners.
410	     *
411	     * @param city the city to count owners for
412	     * @return the number of existing owners in that city
413	     */
414	    private long ownersInCity(String city) {
415	        return this.clinicService.findAllOwners().stream()
416	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
417	            .count();
418	    }
419	
420	    /**
421	     * The maximum number of owners that may be registered on a single day. Once this many owners
422	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
423	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
424	     */
425	    private static final long MAX_OWNERS_PER_DAY = 100L;
426	
427	    /**
428	     * Resolves the effective registration date for a create request: the value supplied in the
429	     * request when present, otherwise the server's current date. The result is the raw effective
430	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
431	     *
432	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
433	     * @return the supplied date, or today when none was supplied
434	     */
435	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
436	        return suppliedDate != null ? suppliedDate : LocalDate.now();
437	    }
438	
439	    /**
440	     * Adjusts a date so it falls on a business day. A Saturday is rolled forward to the following
441	     * Monday and a Sunday to the next day (Monday); any weekday is returned unchanged. Applied to
442	     * the effective registration date so that a weekend value - whether supplied in the request or
443	     * defaulted to the server date - is stored as the next Monday, and every value derived from the
444	     * registration date (such as the membership number's year segment and the daily create-limit
445	     * bucket) uses the adjusted business day.
446	     *
447	     * @param date the effective registration date
448	     * @return the same date when it is a weekday, otherwise the next Monday
449	     */
450	    private LocalDate businessDay(LocalDate date) {
451	        DayOfWeek dayOfWeek = date.getDayOfWeek();
452	        if (dayOfWeek == DayOfWeek.SATURDAY) {
453	            return date.plusDays(2);
454	        }
455	        if (dayOfWeek == DayOfWeek.SUNDAY) {
456	            return date.plusDays(1);
457	        }
458	        return date;
459	    }
460	
461	    /**
462	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
463	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
464	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
465	     * renders as a 429 Too Many Requests response.
466	     *
467	     * @param date the registration date of the owner being created (today)
468	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
469	     */
470	    private void rejectDailyRegistrationLimit(LocalDate date) {
471	        if (ownersRegisteredOn(date) >= MAX_OWNERS_PER_DAY) {
472	            throw new DailyOwnerRegistrationLimitException(date);
473	        }
474	    }
475	
476	    /**
477	     * Counts the existing owners whose {@code registrationDate} equals the given day. Shared by the
478	     * hard daily create limit ({@link #rejectDailyRegistrationLimit(LocalDate)}) and the soft
479	     * {@code bulkSignupWarning} flag ({@link #bulkSignupWarning(LocalDate)}) so both accumulate a
480	     * day's owners identically.
481	     *
482	     * @param date the registration date to count owners for
483	     * @return the number of existing owners registered on that day
484	     */
485	    private long ownersRegisteredOn(LocalDate date) {
486	        return this.clinicService.findAllOwners().stream()
487	            .filter(owner -> date.equals(owner.getRegistrationDate()))
488	            .count();
489	    }
490	
491	    /**
492	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
493	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
494	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
495	     */
496	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
497	
498	    /**
499	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
500	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
501	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
502	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
503	     * without a registration date, such as seed data) is never flagged.
504	     *
505	     * @param date the owner's registration date (the day it was created), or {@code null}
506	     * @return {@code true} if the day already holds more than the warning threshold of owners
507	     */
508	    private boolean bulkSignupWarning(LocalDate date) {
509	        if (date == null) {
510	            return false;
511	        }
512	        return ownersRegisteredOn(date) > BULK_SIGNUP_WARNING_THRESHOLD;
513	    }
514	
515	    /**
516	     * Rejects a create request whose derived {@code identityKey} exactly equals an existing owner's.
517	     * The identity key consolidates the former separate telephone, email and household duplicate
518	     * checks into a single value: {@code normalizedTelephone + '|' + (email or empty) + '|' +
519	     * (householdId or empty)} (see {@link #identityKey(Owner)}). Because the telephone is part of the
520	     * key, two members of the same household (same {@code householdId}) with different telephones have
521	     * different identity keys and are both allowed; only an exact full-key match is a duplicate. A
522	     * collision is reported through a {@link DuplicateOwnerIdentityException}, which the
523	     * {@code ExceptionControllerAdvice} renders as a 409 Conflict response.
524	     *
525	     * @param owner the fully-populated owner being created (telephone, email and household id set)
526	     * @throws DuplicateOwnerIdentityException if an existing owner has the same identity key
527	     */
528	    private void rejectDuplicateIdentity(Owner owner) {
529	        String key = identityKey(owner);
530	        boolean duplicate = existingOwnerMatches(this::identityKey, key);
531	        if (duplicate) {
532	            throw new DuplicateOwnerIdentityException(key);
533	        }
534	    }
535	
536	    /**
537	     * Reduces an owner to its derived {@code identityKey}, formatted
538	     * {@code '<normalizedTelephone>|<email>|<householdId>'}: the owner's telephone reduced to its
539	     * canonical E.164 form (see {@link TelephoneNormalizer#canonicalize(String)}), the owner's
540	     * normalized (lower-cased) email or the empty string when absent (see
541	     * {@link EmailNormalizer#normalize(String)}), and the owner's {@code householdId} or the empty
542	     * string when absent, joined by {@code '|'}. Two owners are duplicates exactly when their whole
543	     * identity keys are equal. The key never contains {@code null} segments, so the create endpoint's
544	     * single duplicate check compares this one value across owners.
545	     *
546	     * @param owner the owner to derive the identity key for
547	     * @return the owner's identity key
548	     */
549	    private String identityKey(Owner owner) {
550	        String telephone = telephoneNormalizer.canonicalize(owner.getTelephone());
551	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
552	        String email = normalizedEmail == null ? "" : normalizedEmail;
553	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
554	        return telephone + "|" + email + "|" + household;
555	    }
556	
557	    /**
558	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
559	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null}
560	     * are ignored. The create endpoint's duplicate checks use this to reduce both an existing owner
561	     * and the owner being created to the same canonical key and reject a match.
562	     *
563	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
564	     * @param key the canonical key of the owner being created
565	     * @return {@code true} if some existing owner shares the key
566	     */
567	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
568	        return this.clinicService.findAllOwners().stream()
569	            .map(keyExtractor)
570	            .filter(Objects::nonNull)
571	            .anyMatch(key::equals);
572	    }
573	
574	    /**
575	     * Delimiter joining the canonical household fields when deriving the shared {@code householdId}.
576	     * A run of whitespace is collapsed to a single space by {@link #canonicalizeHousehold(String)}, so
577	     * this newline can never occur inside a canonical value and the two fields cannot bleed into one
578	     * another across the join.
579	     */
580	    private static final String HOUSEHOLD_KEY_DELIMITER = "\n";
581	
582	    /**
583	     * Reduces a household field ({@code lastName} or {@code address}) to a canonical form for
584	     * case-insensitive, whitespace-insensitive comparison: leading and trailing whitespace is
585	     * trimmed, every run of internal whitespace is collapsed to a single space, and the result is
586	     * lower-cased using {@link java.util.Locale#ROOT} so comparison is locale-independent.
587	     *
588	     * @param value the raw field value, or {@code null}
589	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
590	     */
591	    private String canonicalizeHousehold(String value) {
592	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
593	    }
594	
595	    /**
596	     * Derives the stable, shared {@code householdId} for an owner joining a household via
597	     * {@code sharesHousehold}. The identifier is a deterministic function of the canonical
598	     * {@code lastName} and {@code address} (see {@link #canonicalizeHousehold(String)}), so every
599	     * owner with the same last name at the same address - regardless of casing or spacing - is
600	     * assigned the identical value. It is the first 16 upper-case hex characters of the SHA-256 hash
601	     * of the two canonical fields joined by a delimiter that cannot occur in the input.
602	     *
603	     * @param lastName the last name of the owner being created
604	     * @param address the address of the owner being created
605	     * @return the shared household identifier
606	     */
607	    private String householdId(String lastName, String address) {
608	        String key = canonicalizeHousehold(lastName) + HOUSEHOLD_KEY_DELIMITER + canonicalizeHousehold(address);
609	        return hashPrefix(key, HOUSEHOLD_ID_LENGTH);
610	    }
611	
612	    /**
613	     * Number of leading hex characters of the household hash retained as the shared
614	     * {@code householdId}.
615	     */
616	    private static final int HOUSEHOLD_ID_LENGTH = 16;
617	
618	    /**
619	     * Computes the leading {@code length} upper-case hex characters of the SHA-256 digest of the
620	     * UTF-8 bytes of {@code input}. This is the shared hashing primitive behind the derived
621	     * identifiers that fingerprint owner fields - such as the household-scoped {@code householdId} -
622	     * so every such identifier is produced by the same algorithm and differs only in the value it
623	     * hashes and the number of hex characters it keeps.
624	     *
625	     * @param input the value to hash
626	     * @param length the number of leading hex characters to keep
627	     * @return the leading {@code length} upper-case hex characters of the SHA-256 digest
628	     */
629	    private String hashPrefix(String input, int length) {
630	        try {
631	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
632	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
633	            StringBuilder sb = new StringBuilder(digest.length * 2);
634	            for (byte b : digest) {
635	                sb.append(String.format("%02X", b));
636	            }
637	            return sb.substring(0, length);
638	        } catch (java.security.NoSuchAlgorithmException e) {
639	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
640	        }
641	    }
642	}
